/**
 * Field for showing Function repeatable comments
 */
public class FunctionRepeatableCommentFieldFactory : FieldFactory {
	public static readonly string FIELD_NAME = "Function Repeatable Comment";
	public static readonly GColor COLOR = new GColor("color.fg.listing.comment.repeatable");

	/**
	 * Default constructor
	 */
	public FunctionRepeatableCommentFieldFactory() : base(FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hlProvider the HightLightProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	public FunctionRepeatableCommentFieldFactory(FieldFormatModel model,
			ListingHighlightProvider hlProvider, Options displayOptions, Options fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {

	}

	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		object obj = proxy.getObject();
		if (!enabled || !(obj is Function)) {
			return null;
		}
		int x = startX + varWidth;
		Function f = (Function) obj;
		Program program = f.getProgram();
		string[] commentArr = f.getRepeatableCommentAsArray();
		List<FieldElement> fields = new();
		AttributedString prototype =
			new AttributedString("prototype", CommentColors.REPEATABLE, getMetrics());
		for (int i = 0; i < commentArr.length; i++) {
			fields.add(CommentUtils.parseTextForAnnotations(commentArr[i], program, prototype, i));
		}

		if (commentArr.length > 0) {
			return ListingTextField.createMultilineTextField(this, proxy, fields, x, width,
				hlProvider);
		}
		return null;
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
		ProxyObj<object> proxy = bf.getProxy();
		if (proxy is FunctionProxy) {
			FunctionProxy functionProxy = (FunctionProxy) proxy;
			Function function = functionProxy.getObject();
			return new FunctionRepeatableCommentFieldLocation(function.getProgram(),
				functionProxy.getLocationAddress(), functionProxy.getFunctionAddress(),
				function.getRepeatableCommentAsArray(), row, col);
		}
		return null;
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation loc) {
		if (loc is FunctionRepeatableCommentFieldLocation) {
			FunctionRepeatableCommentFieldLocation floc =
				(FunctionRepeatableCommentFieldLocation) loc;
			return new FieldLocation(index, fieldNum, floc.getRow(), floc.getCharOffset());
		}
		return null;
	}

	/**
	 * @see ghidra.app.util.viewer.field.FieldFactory#acceptsType(int, java.lang.Class)
	 */
	/* @Override */
	public bool acceptsType(int category, Class<object> proxyObjectClass) {
		if (!typeof(Function).isAssignableFrom(proxyObjectClass)) {
			return false;
		}
		return (category == FieldFormatModel.FUNCTION);

	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel, ListingHighlightProvider provider,
			ToolOptions options, ToolOptions fieldOptions) {

		return new FunctionRepeatableCommentFieldFactory(formatModel, provider, options,
			fieldOptions);
	}
}
